WITH base AS (SELECT id, customer_id, store_id, status, amount, discount, shipping_fee, GREATEST(discount, shipping_fee) AS greatest_discount_shipping_fee, COALESCE(channel, 'DIRECT') AS channel_filled FROM orders WHERE channel IN ('mobile', 'partner')) SELECT s.*, top1.order_item_unit_price FROM base s JOIN LATERAL (SELECT c.unit_price AS order_item_unit_price FROM order_items c WHERE c.order_id = s.id ORDER BY c.quantity DESC, c.id DESC LIMIT 1) top1 ON TRUE
